args.sparql:
SELECT DISTINCT ?mother ?motherLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Princess_Maria_of_Greece_and_Denmark dbp:mother ?mother .
  OPTIONAL { ?mother (dbo:birthPlace|dbp:birthPlace) ?birthPlace . }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

